package io.tradeops.importer;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.fasterxml.jackson.databind.*;import io.tradeops.user.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.*;import org.springframework.boot.test.context.*;import org.springframework.mock.web.MockMultipartFile;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.web.servlet.*;import org.springframework.jdbc.core.JdbcTemplate;
@SpringBootTest @AutoConfigureMockMvc class TransactionImportIntegrationTest{@Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired UserRepository users;@Autowired PasswordEncoder encoder;@Autowired JdbcTemplate jdbc;@BeforeEach void setup(){jdbc.execute("delete from import_row_rejections");jdbc.execute("delete from trade_transactions");jdbc.execute("delete from import_runs");users.deleteAll();users.save(new AppUser("operator@tradeops.test",encoder.encode("portfolio-demo"),Role.OPERATOR,true));users.save(new AppUser("viewer@tradeops.test",encoder.encode("portfolio-demo"),Role.VIEWER,true));}@Test void operatorImportsValidRowsAndDuplicateRowIsReviewable()throws Exception{String csv="transactionId,transactionDate,counterpartyName,countryCode,amountUsd,currency,dataOrigin\nTX-101,2026-01-15,EMBER MERIDIAN WORKS,KR,125.00,USD,FICTIONAL\nTX-101,2026-01-16,DUPLICATE,KR,10.00,USD,FICTIONAL";upload(token("operator@tradeops.test"),csv).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COMPLETED_WITH_ERRORS")).andExpect(jsonPath("$.acceptedCount").value(1)).andExpect(jsonPath("$.duplicateCount").value(1));Assertions.assertEquals(1,jdbc.queryForObject("select count(*) from import_row_rejections",Integer.class));}@Test void sameFileIsRejectedWithoutNewRun()throws Exception{String csv="transactionId,transactionDate,counterpartyName,countryCode,amountUsd,currency,dataOrigin\nTX-102,2026-01-15,EMBER MERIDIAN WORKS,KR,125.00,USD,FICTIONAL";String t=token("operator@tradeops.test");upload(t,csv).andExpect(status().isOk());upload(t,csv).andExpect(status().isOk()).andExpect(jsonPath("$.safeErrorCode").value("DUPLICATE_FILE"));Assertions.assertEquals(1,jdbc.queryForObject("select count(*) from import_runs",Integer.class));}@Test void viewerCannotUpload()throws Exception{upload(token("viewer@tradeops.test"),"x").andExpect(status().isForbidden());}ResultActions upload(String token,String csv)throws Exception{return mvc.perform(multipart("/api/v1/imports").file(new MockMultipartFile("file","fictional.csv","text/csv",csv.getBytes())).header("Authorization","Bearer "+token));}String token(String user)throws Exception{MvcResult r=mvc.perform(post("/api/v1/auth/login").contentType("application/json").content("{\"username\":\""+user+"\",\"password\":\"portfolio-demo\"}")).andExpect(status().isOk()).andReturn();return json.readTree(r.getResponse().getContentAsString()).get("accessToken").asText();}}